def assign_existing_stalls_to_tizara(apps, schema_editor):
    """Create the initial service location and keep existing stall data usable."""
    using = schema_editor.connection.alias
    Plaza = apps.get_model("estacionamientos", "Plaza")
    Estacionamiento = apps.get_model("estacionamientos", "Estacionamiento")
    plaza, _ = Plaza.objects.using(using).get_or_create(
        nombre="Tizara",
        estado="Hidalgo",
        municipio="Tizayuca",
        defaults={"activa": True},
    )
    Estacionamiento.objects.using(using).filter(plaza__isnull=True).update(
        plaza_id=plaza.pk
    )


